const input = $input.first();
const binary = input.binary ?? {};

// フォームから渡された画像Binaryをすべて取得
const photoKeys = Object.keys(binary);

return photoKeys.map((key, index) => ({
  json: {
    preferred_language: input.json.preferred_language,
    removal_mode: input.json.removal_mode,
    photo_count: photoKeys.length,
    photo_index: index,
    photo_number: index + 1,
    original_binary_key: key,
    original_filename: binary[key].fileName,
    mime_type: binary[key].mimeType,
  },
  binary: {
    photo: binary[key],
  },
}));

const raw = $json.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error('Gemini returned no analysis text.');
}

let analysis;

try {
  analysis = JSON.parse(
    raw
      .replace(/^```json\s*/i, '')
      .replace(/```$/i, '')
      .trim()
  );
} catch (error) {
  throw new Error(`Invalid Gemini JSON response: ${raw}`);
}

const source = $('Split Photos into Items').item;

return {
  json: {
    preferred_language: source.json.preferred_language,
    removal_mode: source.json.removal_mode,
    photo_count: source.json.photo_count,
    photo_index: source.json.photo_index,
    photo_number: source.json.photo_number,
    original_filename: source.json.original_filename,
    mime_type: source.json.mime_type,

    people_count: Number(analysis.people_count || 0),
    people: Array.isArray(analysis.people) ? analysis.people : [],
    scene_description: analysis.scene_description || '',
  },

  binary: {
    photo: source.binary.photo,
  },
};

return $input.all().map((item) => ({
  json: {
    ...item.json,
    processing_status: 'unchanged',
    people_removed: 0,
  },
  binary: {
    result: item.binary.photo,
  },
}));

const editedItems = $input.all();
const analysisItems = $('Parse Photo Analysis').all();

return editedItems.map((item, index) => {
  const analysis = analysisItems[index]?.json ?? {};

  return {
    json: {
      ...analysis,
      processing_status: 'edited',
      people_removed: analysis.people_count ?? 0,
    },
    binary: {
      result: item.binary.edited,
    },
  };
});

const items = $input.all();

const results = items
  .map((item) => {
    const originalName =
      item.json.original_filename || 'photo.jpg';

    const dotIndex = originalName.lastIndexOf('.');
    const baseName =
      dotIndex > 0
        ? originalName.slice(0, dotIndex)
        : originalName;

    const extension =
      item.binary?.result?.fileExtension ||
      'jpg';

    return {
      json: {
        ...item.json,
        download_filename:
          `${baseName}_cleaned.${extension}`,
      },
      binary: {
        result: {
          ...item.binary.result,
          fileName:
            `${baseName}_cleaned.${extension}`,
        },
      },
    };
  })
  .sort(
    (a, b) =>
      (a.json.photo_index ?? 0) -
      (b.json.photo_index ?? 0)
  );

return results;

const sharedItems = $input.all();
const uploadedItems = $('Upload Temporary Photo').all();
const sourceItems = $('Prepare Download Results').all();

const language =
  sourceItems[0]?.json?.preferred_language || 'en';

const isJapanese = language === 'ja';

const cards = [];

for (let i = 0; i < sharedItems.length; i++) {
  const uploaded = uploadedItems[i];

  if (!uploaded?.json?.id) {
    continue;
  }

  const fileId = uploaded.json.id;

  const imageUrl = uploaded.json.thumbnailLink;

  const downloadUrl =
    `https://drive.google.com/uc?export=download&id=${encodeURIComponent(fileId)}`;

  const downloadLabel = isJapanese
    ? `写真 ${i + 1} をダウンロード`
    : `Download Photo ${i + 1}`;

  cards.push(`
    <div>
      <img
        src="${imageUrl}"
        alt="Cleaned photo ${i + 1}"
        style="max-width:100%;height:auto;"
      >
      <p>
        <a href="${downloadUrl}">
          ${downloadLabel}
        </a>
      </p>
    </div>
  `);
}

const title = isJapanese
  ? '✅ 写真の処理が完了しました！'
  : '✅ Photo processing complete!';

const countText = isJapanese
  ? `${cards.length}枚の写真を処理しました。`
  : `${cards.length} photo${cards.length === 1 ? '' : 's'} ready.`;

const expiryText = isJapanese
  ? '⏰ 写真は24時間後に自動削除されます。期限内にダウンロードしてください。'
  : '⏰ Your photos will be automatically deleted after 24 hours. Please download them before they expire.';

const iphoneText = isJapanese
  ? '📱 iPhone：ダウンロード →「表示」→ 画像を長押し →「“写真”に保存」'
  : '📱 iPhone: Tap Download → Display → press and hold the image → Save to Photos.';

const galleryHtml = `
  <h2>${title}</h2>
  <p>${countText}</p>
  <p><strong>${expiryText}</strong></p>
  ${cards.join('')}
  <p><small>${iphoneText}</small></p>
`;

sharedItems[0].json.gallery_html = galleryHtml;
sharedItems[0].json.gallery_photo_count = cards.length;

return sharedItems;

const uploadedItems = $('Upload Temporary Photo').all();

return uploadedItems.map((item) => ({
  json: {
    file_id: item.json.id,
    file_name: item.json.name,
  },
}));

const items = $input.all();

const photos = items.map((item, index) => {
  const json = item.json;
  const people = Array.isArray(json.people)
    ? json.people
    : [];

  const isJapanese =
    json.preferred_language === 'ja';

  const people_options = people.map((person) => ({
    option: isJapanese
      ? `人物 ${person.id} — ${person.position} — ${person.description}`
      : `Person ${person.id} — ${person.position} — ${person.description}`,
  }));

  return {
    photo_index: json.photo_index ?? index,
    photo_number: json.photo_number ?? index + 1,
    original_filename: json.original_filename,
    mime_type: json.mime_type,
    people_count: json.people_count,
    people,
    people_options,
    binary_key: `photo_${index}`,
  };
});

const binary = {};

items.forEach((item, index) => {
  if (item.binary?.photo) {
    binary[`photo_${index}`] = item.binary.photo;
  }
});

return [
  {
    json: {
      preferred_language:
        items[0]?.json?.preferred_language || 'en',
      removal_mode:
        items[0]?.json?.removal_mode || 'keep_selected',
      photo_count:
        items[0]?.json?.photo_count ?? items.length,
      selection_photo_count: photos.length,
      photos,
    },
    binary,
  },
];

