          <img
            src="${imageUrl}"
            alt="${isJapanese ? '人物選択用の写真' : 'Photo for person selection'}"
            style="width:100%;height:auto;border-radius:8px;display:block;"
          >
        </div>
      `
    });

    fields.push({
      fieldLabel: isJapanese
        ? `写真 ${photo.photo_number}：残したい人物を選択してください`
        : `Photo ${photo.photo_number}: Select the people you want to keep`,
      fieldName: `keep_photo_${photo.photo_index}`,
      fieldType: 'checkbox',
      fieldOptions: {
        values: (photo.people || []).map((person) => ({
          option: isJapanese
            ? `人物 ${person.id} — ${person.position} — ${person.description}`
            : `Person ${person.id} — ${person.position} — ${person.description}`
        }))
      }
    });
  });

  return fields;
})()
}}

