const form = $input.first().json;
const sourceItem = $('Prepare People Selection').first();
const source = sourceItem.json;

const photos = Array.isArray(source.photos)
  ? source.photos
  : [];

const processedPhotos = photos.map((photo) => {
  const fieldName = `keep_photo_${photo.photo_index}`;

  const selectedValues = form[fieldName] ?? [];

  const selectedArray = Array.isArray(selectedValues)
    ? selectedValues
    : [selectedValues];

  const selectedPersonIds = selectedArray
    .map((value) => {
      const match = String(value).match(
        /(?:人物|Person)\s*(\d+)/i
      );

      return match
        ? Number(match[1])
        : null;
    })
    .filter((id) => id !== null);

  const people = Array.isArray(photo.people)
    ? photo.people
    : [];

  const peopleToKeep = people.filter((person) =>
    selectedPersonIds.includes(Number(person.id))
  );

  const peopleToRemove = people.filter(
    (person) =>
      !selectedPersonIds.includes(Number(person.id))
  );

  return {
    ...photo,
    selected_person_ids: selectedPersonIds,
    people_to_keep: peopleToKeep,
    people_to_remove: peopleToRemove,
  };
});

return [
  {
    json: {
      ...source,
      photos: processedPhotos,
    },
    binary: sourceItem.binary,
  },
];

const editedItems = $input.all();
const sourceItems = $('Split Photos for Removal').all();

if (editedItems.length !== sourceItems.length) {
  throw new Error(
    `Edited/source item count mismatch: edited=${editedItems.length}, source=${sourceItems.length}`
  );
}

return editedItems.map((editedItem, index) => {
  const sourceItem = sourceItems[index];
  const source = sourceItem.json;

  if (!editedItem.binary?.edited) {
    throw new Error(
      `Edited binary not found for photo ${source.photo_number}`
    );
  }

  return {
    json: {
      ...source,
      processed: true,
      edited: true,
      processing_mode: 'keep_selected',
    },
    binary: {
      result: editedItem.binary.edited,
    },
  };
});

const input = $input.first();

const photos = Array.isArray(input.json.photos)
  ? input.json.photos
  : [];

return photos.map((photo, index) => {
  const binaryKey =
    photo.binary_key || `photo_${index}`;

  return {
    json: {
      preferred_language:
        input.json.preferred_language,
      removal_mode:
        input.json.removal_mode,
      photo_count:
        input.json.photo_count,
      selection_photo_count:
        input.json.selection_photo_count,
      ...photo,
      selection_index: index,
    },
    binary: {
      photo: input.binary[binaryKey],
    },
  };
});

const selection = $('Prepare People Selection').first().json;
const photos = selection.photos || [];
const uploads = $('Upload Selection Preview').all();

return photos.map((photo, index) => {
  const upload = uploads[index]?.json || {};

  return {
    json: {
      photo_number: photo.photo_number,
      photo_index: photo.photo_index,
      people: photo.people || [],
      preferred_language: selection.preferred_language,
      image_url: upload.thumbnailLink || '',
      drive_file_id: upload.id || '',
    },
  };
});

const sourceItem = $input.first();
const source = sourceItem.json;
const photos = Array.isArray(source.photos)
  ? source.photos
  : [];

return photos.map((photo) => {
  const binaryKey = photo.binary_key;

  if (!binaryKey) {
    throw new Error(
      `Missing binary_key for photo ${photo.photo_number}`
    );
  }

  const binaryData = sourceItem.binary?.[binaryKey];

  if (!binaryData) {
    throw new Error(
      `Binary data not found: ${binaryKey} (photo ${photo.photo_number})`
    );
  }

  return {
    json: {
      preferred_language: source.preferred_language,
      removal_mode: source.removal_mode,

      photo_index: photo.photo_index,
      photo_number: photo.photo_number,
      original_filename: photo.original_filename,
      mime_type: photo.mime_type,

      people_count: photo.people_count,
      people: photo.people,

      selected_person_ids: photo.selected_person_ids,
      people_to_keep: photo.people_to_keep,
      people_to_remove: photo.people_to_remove,

      binary_key: binaryKey,
    },

binary: {
  photo: binaryData,
},
  };
});
